SELECT pl.[QboLineId], eli.[ProjectId], eli.[SubCostCodeId], eli.[Description], ABS(COALESCE(pl.[Amount], eli.[Amount], 0)) AS [AbsAmount] FROM dbo.[Expense] e INNER JOIN qbo.[Purchase] p ON p.[QboId] = e.[QboId] AND p.[RealmId] = e.[RealmId] INNER JOIN qbo.[PurchaseLine] pl ON pl.[QboPurchaseId] = p.[Id] AND pl.[AccountRefName] LIKE N'%NEED TO CATEGORIZE%' LEFT JOIN dbo.[ExpenseLineItem] eli ON eli.[ExpenseId] = e.[Id] AND eli.[QboId] = pl.[QboLineId] AND eli.[RealmId] = p.[RealmId] WHERE e.[Id] = ? ORDER BY [AbsAmount] DESC, TRY_CONVERT(BIGINT, pl.[QboLineId]) ASC, pl.[QboLineId] ASC
